/**
 * Tailwind design-system codegen — generates a typed `tw()` from a real
 * Tailwind design system.
 *
 * Loads the Tailwind design system from a CSS entry (via `@tailwindcss/node`),
 * introspects functional/static utilities, value completions and variants, then
 * writes generated files next to the CSS entry:
 *
 * - `types.d.ts` — `WindVariants`: one key per utility + recursive variant keys,
 *   with literal value unions so the editor autocompletes real Tailwind classes.
 * - `tw.ts` — the small typed `tw` entry;
 * - `tw.runtime.ts` — optional runtime metadata for arbitrary `tw()` calls;
 * - `tw.conflicts.ts` — the conflict-only runtime artifact shared by `tw()`
 *   and `cx()` when exact arbitrary-runtime merging is enabled;
 * - `tw.build.ts` — build-only wildcard candidate metadata.
 *
 */

import { camelCaseProperty } from "./camelcase-property.ts";
import {
	TailwindTypeEmitter,
	utilityKey as emittedUtilityKey,
	type GeneratedTwSources,
} from "./codegen-emitter.ts";
import { TailwindUtilityCatalog } from "./codegen-catalog.ts";
import { loadTailwindDesignSystem, type TailwindDesignSystem } from "./design-system-cache.ts";

import { buildConflicts, detectModifierUtilities } from "./codegen-conflicts.ts";
export { canonicalProps } from "./codegen-conflicts.ts";
import { detectVariantJoin } from "./codegen-variants.ts";
const header =
	"// Generated by pandwind — do not edit. Run `pandwind-codemod tw generate` to regenerate.\n// Editor-only declarations; this file is never imported into the browser runtime.";

type DesignSystemLoader = (css: string, options: { base: string }) => Promise<TailwindDesignSystem>;
type UtilityCatalog = Pick<TailwindUtilityCatalog, "collect" | "expand">;
type TypeEmitter = Pick<TailwindTypeEmitter, "utilities" | "variants" | "runtime">;

export interface DesignSystemCodegen {
	generate(
		css: string,
		base: string,
		options?: GenerateDesignSystemOptions,
	): Promise<GeneratedDesignSystemSource>;
}

export interface DesignSystemCodegenDependencies {
	readonly loader?: DesignSystemLoader;
	readonly catalog?: UtilityCatalog;
	readonly buildConflicts?: typeof buildConflicts;
	readonly detectModifiers?: typeof detectModifierUtilities;
	readonly detectVariantJoin?: typeof detectVariantJoin;
	readonly emitter?: TypeEmitter;
}

export interface GeneratedDesignSystemSource {
	readonly typesDts: string;
	readonly twTs: string;
	readonly twRuntimeTs: string;
	readonly twConflictsTs: string;
	readonly twBuildTs: string;
	/**
	 * Selectors supplied by Tailwind's own variant registry. Consumers that
	 * materialize a Pandwind preset can use these to preserve custom and
	 * configured variant semantics without maintaining a second vocabulary.
	 */
	readonly variantConditions: Readonly<Record<string, string | readonly string[]>>;
	readonly utilityCount: number;
	readonly variantCount: number;
}

function variantConditionSelectors(selector: string): readonly string[] {
	const parts: string[] = [];
	let current = selector.trim();
	for (;;) {
		const nested = /^(@[^{}]+)\s*\{([\s\S]*)\}$/u.exec(current);
		if (nested?.[1] === undefined || nested[2] === undefined) break;
		parts.push(nested[1].trim());
		current = nested[2].trim();
	}
	if (current !== "") parts.push(current);
	return parts;
}

function collectVariantConditions(
	system: TailwindDesignSystem,
): Readonly<Record<string, string | readonly string[]>> {
	const conditions: Record<string, string | readonly string[]> = {};
	for (const variant of system.getVariants()) {
		const add = (name: string, value?: string): void => {
			const selectors = variant
				.selectors(value === undefined ? {} : { value })
				.flatMap(variantConditionSelectors);
			if (selectors.length === 0) return;
			conditions[`_${name}`] = selectors.length === 1 ? selectors[0]! : selectors;
		};
		add(variant.name);
		for (const value of variant.values) {
			const name = variant.hasDash ? `${variant.name}-${value}` : `${variant.name}${value}`;
			add(name, value);
		}
	}
	return conditions;
}

export interface GenerateDesignSystemOptions {
	/**
	 * A generated `@theme {}` block (see generate-theme.ts) injected into the
	 * CSS before Tailwind loads it. Token-derived utilities then flow into
	 * the generated types like any other utility, so tw() autocomplete is
	 * driven by your design system's tokens. Omitted (or empty) = unchanged
	 * behavior.
	 */
	themeBlock?: string;
	/**
	 * Restrict the optional runtime conflict catalog to these Tailwind utility
	 * prefixes. Omitted means the complete catalog; an empty list disables it.
	 * This is safe only when every arbitrary runtime class is covered by the
	 * selected prefixes.
	 */
	conflictUtilities?: readonly string[];
}

const selectConflictUtilities = (
	metadata: ReturnType<typeof buildConflicts>,
	utilities: readonly string[] | undefined,
): ReturnType<typeof buildConflicts> => {
	if (utilities === undefined) return metadata;
	const selected = new Set(utilities);
	const unknown = utilities.filter((utility) => metadata.conflicts[utility] === undefined);
	if (unknown.length > 0)
		throw new Error(
			`pandwind-codemod tw generate: unknown conflict utility prefix(es): ${unknown.join(", ")}`,
		);
	const conflicts = Object.fromEntries(
		Object.entries(metadata.conflicts).filter(([utility]) => selected.has(utility)),
	);
	const availableProperties = new Set(
		Object.values(conflicts).flatMap((values) => Object.values(values).flat()),
	);
	const directionalConflicts =
		metadata.directionalConflicts === undefined
			? undefined
			: {
					kills: Object.fromEntries(
						Object.entries(metadata.directionalConflicts.kills).flatMap(([source, targets]) => {
							const sourceProperties = source.split(",");
							if (!sourceProperties.every((property) => availableProperties.has(property))) {
								return [];
							}
							const filtered = targets.filter((target) =>
								target.split(",").every((property) => availableProperties.has(property)),
							);
							return filtered.length > 0 ? [[source, filtered] as const] : [];
						}),
					),
				};
	return {
		...metadata,
		conflicts,
		compose: metadata.compose.filter((utility) => selected.has(utility)),
		directionalConflicts,
	};
};

/**
 * Generate the generated artifact files for a CSS entry. Exported so tests and
 * tooling can reuse it without writing to disk.
 */
class DefaultDesignSystemCodegen implements DesignSystemCodegen {
	private readonly loader: DesignSystemLoader;
	private readonly catalog: UtilityCatalog;
	private readonly buildConflicts: typeof buildConflicts;
	private readonly detectModifiers: typeof detectModifierUtilities;
	private readonly detectVariantJoin: typeof detectVariantJoin;
	private readonly emitter: TypeEmitter;

	constructor(dependencies: DesignSystemCodegenDependencies = {}) {
		this.loader = dependencies.loader ?? loadTailwindDesignSystem;
		this.catalog = dependencies.catalog ?? new TailwindUtilityCatalog();
		this.buildConflicts = dependencies.buildConflicts ?? buildConflicts;
		this.detectModifiers = dependencies.detectModifiers ?? detectModifierUtilities;
		this.detectVariantJoin = dependencies.detectVariantJoin ?? detectVariantJoin;
		this.emitter = dependencies.emitter ?? new TailwindTypeEmitter(camelCaseProperty);
	}

	async generate(
		css: string,
		base: string,
		options: GenerateDesignSystemOptions = {},
	): Promise<GeneratedDesignSystemSource> {
		const effectiveCss = options.themeBlock ? `${css}\n${options.themeBlock}` : css;
		const system = await this.loader(effectiveCss, { base });
		const functionalKeys = system.utilities.keys("functional");
		const types = this.catalog.collect(system);
		const allMetadata = this.buildConflicts(system, types, functionalKeys);
		this.catalog.expand(types, allMetadata.conflicts);
		const { conflicts, compose, wildcardValues, valueTokens, directionalConflicts } =
			selectConflictUtilities(allMetadata, options.conflictUtilities);
		const modifierCapable = this.detectModifiers(system, types);
		const variants: Array<{ name: string; join: ":" | "-" | "" }> = [];
		for (const variant of system.getVariants()) {
			variants.push({ name: variant.name, join: this.detectVariantJoin(system, variant) });
		}
		const utilityKeyNames = new Set(
			[...types.keys()].map((name) =>
				emittedUtilityKey(name, camelCaseProperty).replace(/^"|"$/g, ""),
			),
		);
		const twSources: GeneratedTwSources = this.emitter.runtime(
			variants,
			conflicts,
			compose,
			wildcardValues,
			valueTokens,
			directionalConflicts,
		);
		return {
			typesDts: `${header}
${this.emitter.utilities(types, modifierCapable)}

${this.emitter.variants(variants, utilityKeyNames)}
`,
			twTs: twSources.entry,
			twRuntimeTs: twSources.runtime,
			twConflictsTs: twSources.conflicts,
			twBuildTs: twSources.build,
			variantConditions: collectVariantConditions(system),
			utilityCount: types.size,
			variantCount: variants.length,
		};
	}
}

export const createDesignSystemCodegen = (
	dependencies: DesignSystemCodegenDependencies = {},
): DesignSystemCodegen => new DefaultDesignSystemCodegen(dependencies);

export async function generateDesignSystem(
	css: string,
	base: string,
	options: GenerateDesignSystemOptions = {},
): Promise<GeneratedDesignSystemSource> {
	return createDesignSystemCodegen().generate(css, base, options);
}
